INSERT INTO "convergence_assessment" ("convergence_id", "status", "clinical_sources", "co1_sources", "co2_sources", "down_weighted_sources", "discounted_sources", "rationale", "synthesis_approach", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (4, 'pending_assessment', '["REF-00983", "REF-00985", "REF-00986", "REF-00984"]', '["REF-00989", "REF-00993"]', '[]', '[]', '["REF-00987", "REF-00988", "REF-00990", "REF-00991", "REF-00992", "REF-00994", "REF-00995"]', 'PROXY: the regulatory stratum supplies the threshold (>=1 T4 international standard present (§2.3; the clause''s ''value directly addressing the parameter'' is unverified — value extraction pending)) and 6 anchoring-tier finding(s) supply the direction. The value is selected most-accommodatingly within what the threshold permits; no source states it. Owner 2026-09-16: ''yes it''s not perfect it''s a proxy''.', NULL, '2026-09-17 22:45:00', 'session_2026-09-17-engine-proxy-inference', NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-006', 'DEC', 'P2', 'OPEN', NULL, NULL, 'RATIO VERSUS PERCENTAGE IS AN UNDECIDED DOCTRINAL QUESTION AND IT SILENTLY NARROWS EVERY GRADIENT DETERMINATION. parse_bound returns None for a value written as a ratio (1:12, 1:20), by its own explicit design, so compose_value builds the interval only from rows stating a percentage. Measured on parameter 3 on 2026-09-17: the value was composed from 2 of 7 governing claims, and the 5 dropped rows state the same physical quantity as a ratio. As of migration 086 the engine SAYS so in value_note instead of dropping them in silence, which is the half that was a plain defect. The half that is a DECISION: 1:20 and 5 percent are the same number in two notations and converting is exact arithmetic with no judgment in it — but the engine refuses cross-unit composition precisely so it cannot invent a figure no source stated, and the corpus stores values as the source writes them on purpose. TODAY THE DROP IS HARMLESS BY LUCK: 1:20 equals the 5 percent row that wins anyway. It will not stay lucky. If the only source stating the gentlest ceiling writes it as a ratio, the engine returns the STEEPER percentage and calls it most-accommodating — the most-accommodating rule inverted by a notation. Needs a ruling: is an exact notation change a conversion this engine may perform? Deciding it inside an engine fix is inventing doctrine where it is least visible.', '2026-09-17 22:13', 'session_2026-09-17-engine-proxy-inference', '2026-09-17 22:13', 'session_2026-09-17-engine-proxy-inference', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "specifications" ("specification_id", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "state", "design_scale", "convergence_id", "confidence_dimensions_present", "confidence_dimensions_absent", "confidence_synthesis_basis", "gap_register_id", "not_applicable_rationale", "tier_basis", "governing_refs", "rule_version", "derivation_sha", "code_floor_only", "value_min", "value_max", "value_unit", "falsification_condition", "has_unverified_sources", "all_sources_disqualified", "regulatory_stratum_only", "created_at", "created_by_session", "updated_at", "updated_by_session", "value_note", "functional_basis", "derivation_rationale", "cultural_claim_anchor", "derivation_paths", "retired_at", "retired_by_session", "retirement_reason", "superseded_by_specification_id", "rests_on_proxy_inference") VALUES (4, 3, 'MOB', NULL, NULL, NULL, 'provisional', 'universal', 4, '["Tier 4-5 standards (2)", "Tier 6 statutory codes (5)", "Anchoring-tier findings supplying direction (6: T1+CO1+T2)"]', '["No source states a value for this parameter at an anchoring tier -- the threshold is regulatory and the direction is inferred, so this is a PROXY determination and not a best-practice claim"]', 'Threshold from the regulatory stratum (>=1 T4 international standard present (§2.3; the clause''s ''value directly addressing the parameter'' is unverified — value extraction pending)), direction from measured findings. A proxy inference under the owner statement of 2026-09-16, marked as one.', NULL, NULL, 'T4-6-only-threshold+T1+CO1+T2-direction(proxy_inference)', '["REF-00987", "REF-00988", "REF-00990", "REF-00991", "REF-00992", "REF-00994", "REF-00995"]', 'pilot-3', 'ac26b2c2cb8e91e61452617f365fc8e8affafca1584875272348f8f7fafc2866', 0, NULL, 5.0, '%', 'Overturned if a source states a value for this parameter at an anchoring tier (the cell then rests on that, not on a proxy), if the findings supplying direction are retracted or re-graded off `finding`, or if the cited threshold editions are superseded. It does NOT become a best-practice claim by more codes agreeing (§2.7), and the proxy step is degenerate without the threshold: ''best outcomes'' alone resolves to the gentlest gradient physically possible, which for a ramp is not a ramp.', 0, 0, 0, '2026-09-17 22:45:00', 'session_2026-09-17-engine-proxy-inference', '2026-09-17 22:45:00', 'session_2026-09-17-engine-proxy-inference', 'composed from 2 of 7 governing claims: 5 state no parsable numeric bound (''1:12'', ''1:15'', ''1:20'') and contribute to the cell''s STATE but not to this interval. No conversion was applied; a ratio is not read as a percentage here', '[{"icf_code": "d410", "mechanism": "Biomechanical \u2014 ambulation, balance, transfer, wheelchair use", "mapping_confidence": "high_predictive", "provenance": "fda-skill-2026-09-13"}, {"icf_code": "d420", "mechanism": "Biomechanical \u2014 ambulation, balance, transfer, wheelchair use", "mapping_confidence": "high_predictive", "provenance": "fda-skill-2026-09-13"}, {"icf_code": "d450", "mechanism": "Biomechanical \u2014 ambulation, balance, transfer, wheelchair use", "mapping_confidence": "high_predictive", "provenance": "fda-skill-2026-09-13"}, {"icf_code": "d455", "mechanism": "Biomechanical \u2014 ambulation, balance, transfer, wheelchair use", "mapping_confidence": "high_predictive", "provenance": "fda-skill-2026-09-13"}, {"icf_code": "d460", "mechanism": "Biomechanical \u2014 ambulation, balance, transfer, wheelchair use", "mapping_confidence": "high_predictive", "provenance": "fda-skill-2026-09-13"}, {"icf_code": "d465", "mechanism": "Biomechanical \u2014 ambulation, balance, transfer, wheelchair use", "mapping_confidence": "high_predictive", "provenance": "fda-skill-2026-09-13"}, {"icf_code": "d470", "mechanism": "Biomechanical \u2014 ambulation, balance, transfer, wheelchair use", "mapping_confidence": "high_predictive", "provenance": "fda-skill-2026-09-13"}, {"icf_code": "d510", "mechanism": "Biomechanical \u2014 ambulation, balance, transfer, wheelchair use", "mapping_confidence": "high_predictive", "provenance": "fda-skill-2026-09-13"}, {"icf_code": "d530", "mechanism": "Biomechanical \u2014 ambulation, balance, transfer, wheelchair use", "mapping_confidence": "high_predictive", "provenance": "fda-skill-2026-09-13"}]', NULL, NULL, 'dual', NULL, NULL, NULL, NULL, 1);
